对于下面的程序段，如果输入 2 则输出的是（　　）

```cpp
#include<bits/stdc++.h>
#define ll long long
using namespace std;
ll f(int n,int k)
{
    ll res=1;
    for(int i=1;i<=k;i++) res=res*(n+1-i)/i;
    return res;
}
int main()
{
    int m;
    ll c1,c2;
    scanf("%d",&m);
    c1=f(m+2,3);
    c2=f(m+4,5);
    printf("%lld",c1*c2);
    return 0;
}
```
